insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('482', '스라밸', 'Seu-Ra-Bael', 'new-slang', null, '공부와 삶의 균형 (Study and Life Balance)', '{"de": "Balance zwischen Lernen und Leben", "en": "Study-life balance", "es": "Equilibrio entre estudio y vida", "ja": "勉強と生活のバランス", "vi": "Cân bằng học tập và cuộc sống"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Ich achte gerade auf meine Lern-Leben-Balance, deshalb lerne ich am Wochenende nicht.", "es": "Últimamente cuido mi equilibrio estudio-vida, así que los fines de semana no estudio.", "ja": "最近は勉強と生活のバランスを大事にしてて、週末は勉強しない。", "vi": "Dạo này tớ giữ cân bằng học - sống nên cuối tuần không học.", "eng": "I''m protecting my study-life balance these days, so I don''t study on weekends.", "kor": "요즘 스라밸 챙기느라 주말엔 공부 안 해."}], "definition": "''Study and Life Balance''를 한국식으로 줄인 말. 직장인이 쓰는 ''워라밸''을 학생 버전으로 바꾼 것으로, 공부만 붙들고 있지 말고 쉬는 시간과 사생활도 챙기자는 뜻이다.", "definition_i18n": {"de": "Koreanische Kurzform von ''Study and Life Balance'', das Schüler-Pendant zu 워라밸 (Work-Life-Balance): Lernen darf nicht alles verschlingen - Erholung und Privatleben gehören dazu.", "en": "A Korean-made shortening of ''Study and Life Balance'', the student counterpart to 워라밸 (work-life balance): do not let studying swallow everything - protect your rest and your private life too.", "es": "Acortamiento coreano de ''Study and Life Balance'', la versión estudiantil del 워라밸 (equilibrio trabajo-vida): que estudiar no se lo coma todo, también hay que cuidar el descanso y la vida privada.", "ja": "「Study and Life Balance」を韓国式に略した語。社会人の「ワラベル(ワークライフバランス)」の学生版で、勉強漬けにならず休息や私生活も大事にしようという意味。", "vi": "Cách rút gọn kiểu Hàn của ''Study and Life Balance'', phiên bản học sinh của 워라밸 (cân bằng công việc - cuộc sống): đừng để việc học nuốt hết thời gian, phải giữ cả lúc nghỉ và đời sống riêng."}}]'::jsonb, '직장인 사이에서 ''워라밸''(Work and Life Balance)이 2017~2018년 유행어가 된 뒤 파생된 말. 2018~2019년 언론이 10대 신조어로 소개하면서 퍼졌다. 영어권에서 실제로 쓰는 표현이 아니라 한국에서 만든 콩글리시다.', '{"de": "Entstand, nachdem 워라밸 (Work-Life-Balance) 2017-2018 unter Büroangestellten zum Modewort wurde; Medien stellten es 2018-2019 als Jugendslang vor. Es ist Konglish - im Englischen sagt das so niemand.", "en": "Derived after 워라밸 (work-life balance) became a buzzword among Korean office workers in 2017-2018; Korean media introduced it as teen slang in 2018-2019. It is Konglish - English speakers do not actually use the phrase.", "es": "Derivó después de que 워라밸 (equilibrio trabajo-vida) se pusiera de moda entre oficinistas en 2017-2018; la prensa lo presentó como jerga adolescente en 2018-2019. Es konglish: en inglés no se usa realmente.", "ja": "社会人の間で「ワラベル(Work and Life Balance)」が2017~18年に流行語となった後に派生。2018~19年に10代の新造語として報道され広まった。英語圏では実際に使われないコングリッシュ。", "vi": "Sinh ra sau khi 워라밸 (cân bằng công việc - cuộc sống) thành từ thời thượng trong giới văn phòng 2017-2018; báo chí giới thiệu như tiếng lóng tuổi teen năm 2018-2019. Đây là Konglish - người bản ngữ tiếng Anh không dùng cụm này."}'::jsonb, '수험생·대학생 사이에서 ''스라밸 지키다 / 챙기다'' 형태로 쓴다. 공부를 게을리한다는 변명이 아니라 번아웃을 막자는 맥락에서 쓰는 게 보통이다.', '{"de": "Prüflinge und Studierende sagen 스라밸 지키다 / 챙기다 (wahren / pflegen). Gemeint ist Burnout-Vorbeugung, keine Ausrede fürs Faulenzen.", "en": "Used by exam-takers and university students as 스라밸 지키다 / 챙기다 (to keep / to look after). It is framed as burnout prevention, not as an excuse to slack off.", "es": "Lo usan opositores y universitarios como 스라밸 지키다 / 챙기다 (mantener / cuidar). Se plantea como prevención del desgaste, no como excusa para vaguear.", "ja": "受験生や大学生が「スラベルを守る・大事にする」の形で使う。サボる言い訳ではなく、燃え尽きを防ぐ文脈で使うのが普通。", "vi": "Học sinh ôn thi và sinh viên dùng ở dạng 스라밸 지키다 / 챙기다 (giữ / lo cho). Nó mang nghĩa phòng kiệt sức, không phải cớ để lười."}'::jsonb, array['워라밸','갓생','번아웃'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Study-life balance"}, {"lang": "🇯🇵 JA", "text": "スタディライフバランス"}, {"lang": "🇨🇳 ZH", "text": "学习与生活的平衡"}, {"lang": "🇻🇳 VI", "text": "Cân bằng học tập - cuộc sống"}, {"lang": "🇪🇸 ES", "text": "Equilibrio estudio-vida"}, {"lang": "🇩🇪 DE", "text": "Lern-Leben-Balance"}]'::jsonb);

